// ⚠️ SAFE DIAGNOSTIC SCRIPT
// This file is auto-generated by the root-level playground-cli.js to prevent accidental destructive database operations.
import { PrismaClient } from './generated/prisma';

const prisma = new PrismaClient();

async function runDiagnostics() {
  console.log('\n🔍 =========================================');
  console.log('🔍 RUNNING SAFE DATABASE DIAGNOSTICS...');
  console.log('🔍 =========================================\n');

  try {
    // 1. Basic System Health (Your original queries)
    const roles = await prisma.role.findMany({ include: { _count: { select: { rolePermissions: true } } } });
    console.log(`👑 ROLES FOUND: ${roles.length}`);
    
    const properties = await prisma.property.findMany({ select: { propertyId: true, propertyName: true, subscriptionStatus: true, subscriptionEndsAt: true, trialEndsAt: true } });
    console.log(`\n🏨 PROPERTIES FOUND: ${properties.length}`);
    properties.forEach(p => {
      const endDate = p.subscriptionEndsAt || p.trialEndsAt || 'N/A';
      console.log(`   - [${p.propertyId}] ${p.propertyName} | Status: ${p.subscriptionStatus} | Ends: ${endDate}`);
    });

    // ============================================================
    // 🎯 TARGETED INVESTIGATION: TEMA PORTSIDE HOTEL (ID: 41)
    // Dates: July 24, 2026 to July 25, 2026
    // ============================================================
    const targetPropertyId = 41;
    const targetCheckIn = new Date('2026-07-24T00:00:00.000Z');
    const targetCheckOut = new Date('2026-07-25T23:59:59.999Z');

    console.log(`\n🎯 =========================================`);
    console.log(`🎯 INVESTIGATING: Tema Portside Hotel (ID: ${targetPropertyId})`);
    console.log(`🎯 DATES: 2026-07-24 to 2026-07-25`);
    console.log(`🎯 =========================================\n`);

    // A. Check if physical rooms actually exist for this property
    const physicalRooms = await prisma.room.findMany({
      where: { propertyId: targetPropertyId },
      select: {
        roomId: true,
        roomNumber: true,
        roomTypeId: true,
        operationalStatus: true,
        housekeepingStatus: true,
      }
    });

    console.log(`🚪 PHYSICAL ROOMS IN DATABASE: ${physicalRooms.length}`);
    if (physicalRooms.length === 0) {
      console.log('   ⚠️ CRITICAL: No physical rooms exist for this property! You must create rooms first.');
    } else {
      physicalRooms.forEach(r => {
        const isAvailable = r.operationalStatus === 'Available' && r.housekeepingStatus === 'Clean';
        const statusIcon = isAvailable ? '✅' : '⚠️';
        console.log(`   ${statusIcon} Room ${r.roomNumber} (Type ID: ${r.roomTypeId}) | Ops: ${r.operationalStatus} | HK: ${r.housekeepingStatus}`);
      });
    }

    // B. Check for OVERLAPPING reservations that would block these dates
    const overlappingBookings = await prisma.reservationRoom.findMany({
      where: {
        room: { propertyId: targetPropertyId },
        reservation: {
          status: { in: ['Confirmed', 'CheckedIn'] } // Ignore Cancelled/Pending
        },
        OR: [
          {
            checkInDate: { lte: targetCheckOut },
            checkOutDate: { gte: targetCheckIn }
          }
        ]
      },
            include: {
        room: { select: { roomId: true, roomNumber: true } }, // 🌟 FIX: Added roomId
        reservation: { 
          select: { 
            reservationId: true, 
            status: true, 
            checkInDate: true, 
            checkOutDate: true,
            platformGuest: { select: { fullName: true } },
            propertyGuest: { select: { fullName: true } }
          } 
        }
      },
      orderBy: { checkInDate: 'asc' }
    });

    console.log(`\n📅 OVERLAPPING BOOKINGS FOUND: ${overlappingBookings.length}`);
    if (overlappingBookings.length === 0) {
      console.log('   ✅ No reservations are blocking these dates.');
    } else {
      overlappingBookings.forEach(br => {
        const guestName = br.reservation.platformGuest?.fullName || br.reservation.propertyGuest?.fullName || 'Unknown Guest';
        console.log(`   🚫 Room ${br.room.roomNumber} is BLOCKED by Reservation #${br.reservation.reservationId}`);
        console.log(`      Guest: ${guestName} | Status: ${br.reservation.status}`);
        console.log(`      Dates: ${br.reservation.checkInDate.toDateString()} to ${br.reservation.checkOutDate.toDateString()}`);
      });
    }

    // C. Room Type Availability Summary
    console.log(`\n📊 ROOM TYPE AVAILABILITY SUMMARY:`);
    const roomTypes = await prisma.roomType.findMany({
      where: { propertyId: targetPropertyId },
      include: {
        _count: { select: { rooms: true } }
      }
    });

    roomTypes.forEach(rt => {
      const availableRooms = physicalRooms.filter(r => 
        r.roomTypeId === rt.roomTypeId && 
        r.operationalStatus === 'Available' && 
        r.housekeepingStatus === 'Clean'
      );
      const blockedRooms = overlappingBookings.filter(br => 
        // We need to find the roomTypeId for this booking. Since we didn't select it above, let's do a quick match
        physicalRooms.find(pr => pr.roomId === br.room.roomId)?.roomTypeId === rt.roomTypeId
      ).length;
      
      const trulyFree = availableRooms.length - blockedRooms;

      console.log(`   🛏️ ${rt.typeName} (GH₵${rt.basePrice})`);
      console.log(`      Total: ${rt._count.rooms} | Available & Clean: ${availableRooms.length} | Blocked by bookings: ${blockedRooms} | ✅ TRULY FREE: ${trulyFree}`);
    });

  } catch (error: any) {
    console.error('❌ DATABASE ERROR:', error.message);
  } finally {
    await prisma.$disconnect();
    console.log('\n🔍 =========================================');
    console.log('🔍 DIAGNOSTICS COMPLETE. Copy the output above!');
    console.log('🔍 =========================================\n');
  }
}

runDiagnostics();